#!/usr/bin/env python3
"""Integration check: render QR modules generated by the JS engine and decode with OpenCV.
OpenCV is test-only, not a dependency of QR Studio.
"""
import json, subprocess, sys
from pathlib import Path
try:
    import cv2
    import numpy as np
except Exception as exc:
    print(f"SKIP: OpenCV not available in test environment ({exc})")
    raise SystemExit(0)
root = Path(__file__).resolve().parents[1]
script = r'''
require(process.argv[1]);
const {QRCode, ErrorCorrection}=global.FogQR;
const payload=process.argv[2]; const level=process.argv[3]||'M';
const qr=new QRCode(0,ErrorCorrection[level]); qr.addData(payload); qr.make();
const n=qr.getModuleCount(); const m=[];
for(let y=0;y<n;y++){const r=[];for(let x=0;x<n;x++)r.push(qr.isDark(y,x)?1:0);m.push(r)}
process.stdout.write(JSON.stringify({payload,n,m}));
'''
engine = str(root / 'site' / 'lib' / 'qr-engine.js')
cases = [
    ('https://example.com/qr-studio?source=test', 'M'),
    ('Ciao mondo — città 🌍', 'Q'),
]
detector = cv2.QRCodeDetector()
for payload, level in cases:
    raw = subprocess.check_output(['node', '-e', script, engine, payload, level], text=True)
    result = json.loads(raw)
    quiet, scale = 4, 10
    n = result['n']
    arr = np.ones((n+quiet*2, n+quiet*2), dtype=np.uint8) * 255
    for y, row in enumerate(result['m']):
        for x, value in enumerate(row):
            if value:
                arr[y+quiet, x+quiet] = 0
    arr = cv2.resize(arr, (arr.shape[1]*scale, arr.shape[0]*scale), interpolation=cv2.INTER_NEAREST)
    decoded, points, _ = detector.detectAndDecode(arr)
    if decoded != payload:
        raise AssertionError(f"Decode mismatch. expected={payload!r}, got={decoded!r}")
fixture = root / 'site' / 'assets' / 'qr-studio-test.png'
fixture_image = cv2.imread(str(fixture))
if fixture_image is None:
    raise AssertionError(f'Could not load test QR fixture: {fixture}')
fixture_decoded, fixture_points, _ = detector.detectAndDecode(fixture_image)
expected_fixture = 'QR-STUDIO-IMAGE-IMPORT-TEST|FOGLABS|PASS'
if fixture_decoded != expected_fixture:
    raise AssertionError(f'Test QR fixture mismatch: {fixture_decoded!r}')
print(f"OpenCV decode smoke: {len(cases)} generated QR matrices plus the packaged image-import fixture decoded correctly.")
